// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(uint256 salt) public {
        string memory v = c.version();
        bytes memory vBytes = bytes(v);
        assertTrue(
            keccak256(vBytes) == keccak256(bytes("1.0.0")),
            "version() must return the configured 1.0.0"
        );
    }
}
